from __future__ import annotations

from pathlib import Path

from fastapi import FastAPI, HTTPException, Query, Response, status
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from app.db import create_note, delete_note, get_note, initialize_db, list_notes, update_note

app = FastAPI(title="Notes API")
initialize_db()
app.mount("/static", StaticFiles(directory=Path(__file__).resolve().parent / "static"), name="static")


@app.on_event("startup")
async def startup_event() -> None:
    initialize_db()


@app.post("/notes", status_code=status.HTTP_201_CREATED)
def create_note_endpoint(note: dict) -> dict:
    # FastAPI will validate the incoming JSON against the expected structure
    # if we were using a Pydantic model, but here we rely on the DB layer
    # or explicit validation if needed. However, to maintain the 422 behavior
    # for missing fields, we should probably keep the Pydantic model for input
    # validation but bypass it for output. 
    # The plan says "Refactor app/db.py... Update app/main.py... FastAPI will serialize the dicts directly."
    # To preserve the 422 validation errors for input, we must keep the Pydantic models for INPUT.
    # The optimization is for OUTPUT (DB -> API response).
    # So we need to import NoteCreate/NoteUpdate for input validation, but return dicts.
    from app.models import NoteCreate, NoteUpdate

    # Re-parse to ensure validation happens
    validated = NoteCreate(**note)
    return create_note(validated.title, validated.body, validated.tags)


@app.get("/notes/{note_id}")
def read_note(note_id: int) -> dict:
    note = get_note(note_id)
    if note is None:
        raise HTTPException(status_code=404, detail="Note not found")
    return note


@app.get("/notes")
def list_notes_endpoint(
    q: str | None = Query(default=None, description="Substring search over title or body."),
    tag: list[str] = Query(default_factory=list),
    offset: int = Query(default=0, ge=0),
    limit: int = Query(default=20, ge=1, le=100),
) -> dict[str, object]:
    clean_tags = [item.strip() for item in tag if isinstance(item, str) and item.strip()]
    items, total = list_notes(search_text=q, tags_filter=clean_tags, offset=offset, limit=limit)
    return {
        "items": items,
        "total": total,
        "offset": offset,
        "limit": limit,
    }


@app.put("/notes/{note_id}")
def update_note_endpoint(note_id: int, note: dict) -> dict:
    from app.models import NoteUpdate
    validated = NoteUpdate(**note)
    updated = update_note(note_id, validated.title, validated.body, validated.tags)
    if updated is None:
        raise HTTPException(status_code=404, detail="Note not found")
    return updated


@app.delete("/notes/{note_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_note_endpoint(note_id: int) -> Response:
    deleted = delete_note(note_id)
    if not deleted:
        raise HTTPException(status_code=404, detail="Note not found")
    return Response(status_code=204)


@app.get("/", include_in_schema=False)
def read_index() -> FileResponse:
    return FileResponse(Path(__file__).resolve().parent / "static" / "index.html")


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=8000)
